import json, sys

data = json.load(sys.stdin)
inner = json.loads(data['result'])
exps = inner['data']['experiments']

# Deep search for any key containing 'worker' at any nesting level
def find_worker_refs(obj, path=''):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'worker' in k.lower():
                results.append((path + '.' + k, v))
            results.extend(find_worker_refs(v, path + '.' + k))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            results.extend(find_worker_refs(v, path + f'[{i}]'))
    elif isinstance(obj, str) and 'worker' in obj.lower():
        results.append((path + ' (value)', obj))
    return results

all_refs = []
for exp_id, exp_data in exps.items():
    refs = find_worker_refs(exp_data, exp_id)
    if refs:
        all_refs.extend(refs)

if all_refs:
    print(f'Found {len(all_refs)} worker references:')
    for path, val in all_refs:
        print(f'  {path}: {val}')
else:
    print('No worker references found in any experiment field.')

# Also check: what fields do experiments have? Sample a few
print()
print('=== SAMPLE EXPERIMENT FIELD KEYS ===')
sampled = 0
for exp_id, exp_data in exps.items():
    if isinstance(exp_data, dict):
        print(f'{exp_id}: {sorted(exp_data.keys())}')
        sampled += 1
        if sampled >= 5:
            break

# Check ALL unique keys across all experiments
print()
print('=== ALL UNIQUE FIELD KEYS ACROSS ALL EXPERIMENTS ===')
all_keys = set()
for exp_data in exps.values():
    if isinstance(exp_data, dict):
        all_keys.update(exp_data.keys())
        # also spec sub-keys
        if 'spec' in exp_data and isinstance(exp_data['spec'], dict):
            all_keys.update('spec.' + k for k in exp_data['spec'].keys())
print(sorted(all_keys))
"

