import json, sys, re

data = json.load(sys.stdin)
inner = json.loads(data['result'])
exps = inner['data']['experiments']

# Extract all worker IDs mentioned in notes
worker_pattern = re.compile(r'[Ww]orker\s+(worker_\w+)')
worker_refs = {}
for exp_id, exp_data in exps.items():
    if isinstance(exp_data, dict):
        notes = exp_data.get('notes', '')
        if notes:
            matches = worker_pattern.findall(notes)
            if matches:
                worker_refs[exp_id] = matches

print('=== WORKER REFERENCES EXTRACTED FROM NOTES ===')
all_workers = set()
for exp_id, workers in worker_refs.items():
    for w in workers:
        all_workers.add(w)
    print(f'  {exp_id}: {workers}')

print()
print('=== UNIQUE WORKERS ===')
for w in sorted(all_workers):
    print(f'  {w}')

# Also get ALL experiments that have notes (for completeness)
print()
print('=== ALL EXPERIMENTS WITH NOTES ===')
for exp_id, exp_data in sorted(exps.items()):
    if isinstance(exp_data, dict) and exp_data.get('notes'):
        print(f'  {exp_id}: {exp_data[\"notes\"][:200]}')
"
